const $=id=>document.getElementById(id);let catalog,tileRules,logicVisible=false,hiddenItems=[],category='all',query='',group='',page=1,onlySelected=false,current=null,grid=false,showHidden=false;const PAGE=30;let selections={};try{selections=JSON.parse(localStorage.getItem('shuihu.asset-plan.v1')||'{}');}catch{}
const notes={'ui-hd':'8套新界面底板；文字由游戏使用高清字体绘制，候选待验收。',items:'按物品编号对应的高清图标候选，108个已恢复名称的条目全部列出；带“待生成”图片的是排队任务，不能计入完成数。图标对应关系和透明背景仍需校验。','attack-effects':'按武器或道具编号区分的攻击动画样例；点击详情中的播放链接。',all:'地图正在统一校准裁切和外部遮罩；原错误版本已保留供对照。物品108种、人物60组及新增头像、界面已生成候选。完整进度与错误项见制作队列。',maps:'116张原版地图 + 348张重绘拼接候选。三种画风均待检查接缝、招牌和遮挡；隐藏点与格值来自原版数据。','map-banks':'31 组地图资源按图块、组合方式和调色板区分。先重画这些可复用组件，可以同时改善多张地图。',characters:'60 组独立精灵资源，共 664 帧切片。另有60组九帧重绘候选；可打开详情播放正背左右步行。原始额外帧语义仍需核对。',portraits:'原版40个头像；高清重绘39张已生成，1张服务拒绝已记录。头像身份、配色与裁边仍待逐张校验。',fonts:'8 套原版字模，共 1,825 个字形。新版游戏正在改用可缩放的系统字体，这里保留字模作为原文校对参考。',ui:'40 套界面图块。灰度图表示像素索引，尚未全部还原最终配色与拼接布局。',title:'原版标题画面的静态还原，不包含闪烁和渐变时序。'};
function notify(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').classList.remove('show'),2300);}
function persist(){try{localStorage.setItem('shuihu.asset-plan.v1',JSON.stringify(selections));}catch{notify('本地存储不可用，请导出清单备份');}$('planCount').textContent=Object.keys(selections).length;}
function catName(id){return catalog.categories.find(c=>c.id===id)?.name??'素材';}
function desc(item){const d=item.details;if(item.category==='maps')return `${d.widthTiles} × ${d.heightTiles} 格 · ${item.width} × ${item.height}`;if(item.category==='map-banks')return `${d.metatileCount} 个组合块 · 用于 ${item.mapCount} 张地图`;if(item.category==='characters')return `${d.frameCount} 帧 · 单帧 ${d.frameWidth} × ${d.frameHeight}`;if(item.category==='fonts')return `${d.glyphCount} 个字形 · ${d.glyphWidth} × ${d.glyphHeight}`;return `${item.width} × ${item.height} 像素`;}
function makeButton(text,fn,cls=''){const b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=fn;return b;}
function setCategory(id){category=id;page=1;group='';$('groupFilter').value='';render();}
function matches(){return catalog.items.filter(i=>(category==='all'||i.category===category)&&(category!=='all'||i.productionState!=='rejected')&&(!onlySelected||selections[i.id])&&(!group||(i.details.mapId??'').startsWith(group)||(i.mapIds??[]).some(id=>id.startsWith(group)))&&(!query||[i.name,i.id,i.bankId,JSON.stringify(i.details.characterIds??[]),JSON.stringify(i.details.portraitIds??[])].join(' ').toLowerCase().includes(query)));}
function render(){const all=matches(),pages=Math.max(1,Math.ceil(all.length/PAGE));page=Math.min(page,pages);$('categoryTitle').textContent=category==='all'?'全部素材':catName(category);$('categoryNote').textContent=notes[category];$('resultCount').textContent=`${all.length} 项素材`;$('categories').replaceChildren();for(const c of [{id:'all',name:'全部素材',count:catalog.items.length},...catalog.categories]){const b=makeButton(c.name,()=>setCategory(c.id),c.id===category?'active':'');const n=document.createElement('span');n.textContent=c.count;b.append(n);$('categories').append(b);}$('gallery').replaceChildren();for(const i of all.slice((page-1)*PAGE,page*PAGE)){const card=document.createElement('article');card.className='asset'+(selections[i.id]?' selected':'');const open=makeButton('',()=>openDetail(i.id),'asset-open');open.setAttribute('aria-label',`查看${i.name}`);const preview=document.createElement('div');preview.className='asset-preview';const image=document.createElement('img');image.src=i.image+(i.generated&&i.sha256?'?v='+i.sha256.slice(0,12):'');image.alt=i.name;image.loading='lazy';image.decoding='async';preview.append(image);const info=document.createElement('div');info.className='asset-info';const label=document.createElement('div');label.className='asset-category';label.textContent=i.productionState==='rejected'?'退回修复 · 禁止使用':i.productionState==='queued'?'排队中':i.productionState==='running'?'生成中':catName(i.category);const title=document.createElement('div');title.className='asset-label';const name=document.createElement('strong');name.textContent=i.name;title.append(name);const meta=document.createElement('small');meta.textContent=desc(i);info.append(label,title,meta);open.append(preview,info);const pick=makeButton(selections[i.id]?'✓':'+',()=>{toggle(i.id);render();},'asset-pick');pick.setAttribute('aria-label',`${selections[i.id]?'移除':'选择'}${i.name}`);card.append(open,pick);$('gallery').append(card);}$('empty').hidden=!!all.length;$('pageInfo').textContent=`${page} / ${pages}`;$('previous').disabled=page===1;$('next').disabled=page===pages;$('groupFilter').hidden=!['all','maps','map-banks'].includes(category);persist();}
function toggle(id){if(selections[id])delete selections[id];else selections[id]={note:'',selectedAt:new Date().toISOString()};persist();}
function meta(label,value){const term=document.createElement('dt'),def=document.createElement('dd');term.textContent=label;def.textContent=value;$('metadata').append(term,def);}
function openDetail(id){current=catalog.items.find(i=>i.id===id);if(!current)return;grid=false;showHidden=false;logicVisible=false;$('detailTitle').textContent=current.name;$('detailCategory').textContent=catName(current.category);$('detailImage').src=current.image+(current.generated&&current.sha256?'?v='+current.sha256.slice(0,12):'');$('detailImage').alt=current.name;$('originalLink').href=current.image;$('metadata').replaceChildren();meta('素材编号',current.id);if(current.previewUrl){const link=document.createElement('a');link.href=current.previewUrl;link.target='_blank';link.rel='noopener';link.textContent=current.category==='characters'?'▶ 查看四方向步行':'▶ 播放攻击动画';$('metadata').append(link);}meta('原图尺寸',`${current.width} × ${current.height}`);if(current.category==='maps'){meta('地图大小',`${current.details.widthTiles} × ${current.details.heightTiles} 格`);meta('调查奖励',`${hiddenItems.filter(i=>i.mapId===current.details.mapId).length} 处`);}if(current.mapCount!=null)meta('地图复用',`${current.mapCount} 张地图`);if(current.details.frameCount)meta('原始帧数',`${current.details.frameCount} 帧`);if(current.details.characterIds)meta('角色索引',current.details.characterIds.join('、'));if(current.details.portraitIds)meta('头像索引',current.details.portraitIds.join('、'));meta('任务状态',current.productionState??'original');meta('制作状态',['hd-candidates','items','attack-effects'].includes(current.category)||current.generated?'已生成，待校验':'原版素材，等待挑选');document.querySelector('.state-label').textContent=['hd-candidates','items','attack-effects'].includes(current.category)||current.generated?'重绘候选 · 待校验':'原版素材';$('confidenceNote').textContent=current.confidence.limit;$('assetNote').value=selections[id]?.note??'';$('chooseAsset').textContent=selections[id]?'已加入 · 从清单移除':'加入制作清单';$('related').replaceChildren();const related=current.category==='maps'?[current.bankId]:current.mapIds?.map(id=>'map-'+id)??[];$('relatedTitle').textContent=current.category==='maps'?'这张地图使用的图块':'使用这组图块的地图';$('relatedTitle').hidden=!related.length;for(const rid of related){const item=catalog.items.find(i=>i.id===rid);if(item)$('related').append(makeButton(item.category==='maps'?item.details.mapId:'查看组合图块',()=>openDetail(rid)));}$('extraPreviews').replaceChildren();for(const p of current.baseTilePreviews??[]){const details=document.createElement('details'),summary=document.createElement('summary'),image=document.createElement('img');summary.textContent=`查看 8 × 8 基础图块 · 调色板 ${p.palette}`;image.src=p.image;image.loading='lazy';image.alt=summary.textContent;details.append(summary,image);$('extraPreviews').append(details);}$('hiddenToggle').hidden=current.category!=='maps';$('logicToggle').hidden=current.category!=='maps';$('tileRuleInfo').textContent=['maps','map-banks'].includes(current.category)?'点预览中的一格，查看该图块对应的原始规则。战场地形与兵种限制仍待核对。':'';$('gridToggle').hidden=!['maps','map-banks'].includes(current.category);drawOverlays();if(!$('detail').open)$('detail').showModal();}
function drawOverlays(){const cell=current.category==='maps'?current.width/current.details.widthTiles:32;$('logicToggle').setAttribute('aria-pressed',String(logicVisible));$('logicOverlay').replaceChildren();if(logicVisible&&current.category==='maps'){const m=tileRules.maps[current.details.mapId];m.logic.forEach((v,index)=>{const mark=document.createElement('span');Object.assign(mark.style,{position:'absolute',left:`${index%m.width/m.width*100}%`,top:`${Math.floor(index/m.width)/m.height*100}%`,width:`${100/m.width}%`,height:`${100/m.height}%`,background:v===0?'#33a36f55':v<80?'#ddab3988':v>=128&&v<=175?'#8556c388':'#db534e66'});$('logicOverlay').append(mark);});$('tileRuleInfo').textContent='探索规则：绿＝普通通行；黄＝踏入事件；红＝阻挡或接触事件；紫＝邻接调查。静态预览不含NPC、剧情动态覆写；不能用此颜色推断战场水面或兵种限制。';}$('gridToggle').setAttribute('aria-pressed',String(grid));$('hiddenToggle').setAttribute('aria-pressed',String(showHidden));const over=$('gridOverlay');over.style.display=grid?'block':'none';over.style.backgroundImage='linear-gradient(to right,#ffffff66 1px,transparent 1px),linear-gradient(to bottom,#ffffff66 1px,transparent 1px)';over.style.backgroundSize=`${cell/current.width*100}% ${cell/current.height*100}%`;$('hiddenOverlay').replaceChildren();if(showHidden)for(const p of hiddenItems.filter(i=>i.mapId===current.details.mapId)){const marker=document.createElement('span');Object.assign(marker.style,{left:`${p.x*cell/current.width*100}%`,top:`${p.y*cell/current.height*100}%`,width:`${cell/current.width*100}%`,height:`${cell/current.height*100}%`});$('hiddenOverlay').append(marker);}}
function renderPlan(){const h=$('planItems');h.replaceChildren();const ids=Object.keys(selections);if(!ids.length){const p=document.createElement('p');p.textContent='还没有选择素材。点击素材卡片上的“＋”加入。';h.append(p);}for(const id of ids){const item=catalog.items.find(i=>i.id===id);if(!item)continue;const row=document.createElement('div');row.className='plan-row';const image=document.createElement('img');image.src=item.image;image.alt='';const text=document.createElement('div');text.textContent=item.name;const note=document.createElement('small');note.textContent=selections[id].note||desc(item);text.append(note);row.append(image,text,makeButton('移除',()=>{toggle(id);renderPlan();render();}));h.append(row);}$('exportPlan').disabled=!ids.length;$('clearPlan').disabled=!ids.length;}
$('search').oninput=e=>{query=e.target.value.trim().toLowerCase();page=1;render();};$('groupFilter').onchange=e=>{group=e.target.value;page=1;render();};$('previous').onclick=()=>{page--;render();document.querySelector('.library').scrollIntoView({block:'start',behavior:'smooth'});};$('next').onclick=()=>{page++;render();document.querySelector('.library').scrollIntoView({block:'start',behavior:'smooth'});};$('pixelToggle').onclick=()=>{const smooth=document.body.classList.toggle('smooth');$('pixelToggle').setAttribute('aria-pressed',String(!smooth));};$('selectedOnly').onclick=()=>{onlySelected=!onlySelected;$('selectedOnly').setAttribute('aria-pressed',String(onlySelected));page=1;render();};$('closeDetail').onclick=()=>$('detail').close();$('closePlan').onclick=()=>$('plan').close();for(const id of ['detail','plan'])$(id).addEventListener('click',e=>{if(e.target===$(id)){const r=$(id).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$(id).close();}});
$('chooseAsset').onclick=()=>{toggle(current.id);$('chooseAsset').textContent=selections[current.id]?'已加入 · 从清单移除':'加入制作清单';$('assetNote').value=selections[current.id]?.note??'';render();};$('assetNote').oninput=e=>{selections[current.id]??={note:'',selectedAt:new Date().toISOString()};selections[current.id].note=e.target.value;persist();$('chooseAsset').textContent='已加入 · 从清单移除';};$('detail').addEventListener('close',render);$('gridToggle').onclick=()=>{grid=!grid;drawOverlays();};$('hiddenToggle').onclick=()=>{showHidden=!showHidden;drawOverlays();};$('planButton').onclick=()=>{renderPlan();$('plan').showModal();};$('clearPlan').onclick=()=>{selections={};persist();renderPlan();render();notify('已清空选择，原始素材不受影响');};$('exportPlan').onclick=()=>{const data={project:'水浒传素材重构',version:1,generatedAt:new Date().toISOString(),stage:'selection_only_no_generation',items:Object.entries(selections).map(([id,value])=>{const item=catalog.items.find(i=>i.id===id);return {id,name:item?.name,category:item?.category,sourceImage:item?.image,sourceSha256:item?.sha256,...value};})};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='水浒传-素材制作清单.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{[catalog,{items:hiddenItems},tileRules]=await Promise.all(['data/catalog.json','data/hidden-items.json','data/tile-rules.json'].map(path=>fetch(path,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('素材索引读取失败');return r.json();})));for(const g of [...new Set(catalog.items.filter(i=>i.category==='maps').map(i=>i.details.mapId.slice(0,2)))].sort()){const opt=document.createElement('option');opt.value=g;opt.textContent=`第 ${parseInt(g,16)} 组地图`;$('groupFilter').append(opt);}catalog.items.sort((a,b)=>Number(!!b.generated)-Number(!!a.generated));render();}catch(e){$('resultCount').textContent='载入失败';$('empty').hidden=false;$('empty').textContent=e.message+'，请刷新重试。';}

$('logicToggle').onclick=()=>{logicVisible=!logicVisible;drawOverlays();};
function ruleLabel(v){return v===0?'普通通行':v<80?'可通行，踏入触发事件':v===80?'阻挡，无调查事件':v<128?'阻挡，尝试进入触发接触事件':v<=175?'阻挡，可邻接调查':'探索语义待核对';}
$('detailImage').onclick=event=>{if(!['maps','map-banks'].includes(current.category))return;const r=event.target.getBoundingClientRect(),x=Math.floor((event.clientX-r.left)/r.width*(current.details.widthTiles??current.width/32)),y=Math.floor((event.clientY-r.top)/r.height*(current.details.heightTiles??current.height/32));let bank=current.id,tile=y*Math.ceil(current.width/32)+x,placed='';if(current.category==='maps'){const m=tileRules.maps[current.details.mapId],index=y*m.width+x;tile=m.graphics[index];bank=m.bankId;placed=`地图格 (${x}, ${y})：${ruleLabel(m.logic[index])}，原始值 0x${m.logic[index].toString(16).padStart(2,'0')}。\n`;}const info=tileRules.banks[bank]?.[tile];if(!info){$('tileRuleInfo').textContent='此格是图集空位，没有地图引用。';return;}const rules=Object.entries(info.values).map(([v,n])=>`0x${Number(v).toString(16).padStart(2,'0')}（${ruleLabel(Number(v))}）：${n} 处`).join('；');$('tileRuleInfo').textContent=`${placed}组合块 #${tile}，用于 ${info.maps.length} 张地图。\n原始格值分布（探索语义）：${rules}。\n图块只决定外观，各位置的逻辑格值仍独立保留。水面、桥与各兵种的战场通行规则尚未验证，不在这里猜测。`;};
